{% extends "templates/print/ph_basis.html" %}
{% block titel %}Anfrage {{ doc.name }}{% endblock %}
{% block kopfrechts %}Anfrage {{ doc.name }}<br>Eingang {{ ph_datum(doc.eingang) }}<br>Status {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>{{ doc.titel }}</h1>
<div class="ph-feld"><b>Art</b> {{ _(doc.art) }}</div>
<div class="ph-feld"><b>Name</b> {{ doc.anrede or "" }} {{ doc.vorname or "" }} {{ doc.nachname }}{% if doc.firma %}, {{ doc.firma }}{% endif %}</div>
<div class="ph-feld"><b>E-Mail</b> {{ doc.email or "–" }}</div>
<div class="ph-feld"><b>Telefon</b> {{ doc.telefon or "–" }}</div>
{% if doc.plz_ort or doc.land %}<div class="ph-feld"><b>Ort</b> {{ doc.plz_ort or "" }} {{ doc.land or "" }}</div>{% endif %}
{% if doc.projektart %}<div class="ph-feld"><b>Es geht um</b> {{ doc.projektart }}{% if doc.objektart %} · {{ doc.objektart }}{% endif %}</div>{% endif %}
<h2>Anliegen</h2>
<div>{{ doc.anliegen }}</div>
{% if doc.produkte %}
<h2>Produkte</h2>
<table class="ph-tabelle"><thead><tr><th>Produkt</th><th>Marke</th><th class="zahl">Menge</th></tr></thead><tbody>
{% for p in doc.produkte %}<tr><td>{{ p.produkt_name or p.produkt_slug }}</td><td>{{ p.marke or "" }}</td><td class="zahl">{{ p.menge }}</td></tr>{% endfor %}
</tbody></table>
{% endif %}
<h2>Bearbeitung</h2>
<div class="ph-feld"><b>Zuständig</b> {{ frappe.db.get_value("User", doc.zugewiesen_an, "full_name") if doc.zugewiesen_an else "–" }}</div>
<div class="ph-feld"><b>Nächster Schritt</b> {{ doc.naechster_schritt or "–" }}</div>
<div class="ph-feld"><b>Wiedervorlage</b> {{ ph_datum(doc.wiedervorlage) or "–" }}</div>
{% if doc.upload_anzahl %}<div class="ph-feld"><b>Uploads</b> {{ doc.upload_anzahl }} Datei(en) der Website</div>{% endif %}
<p class="ph-hinweis">Interner Ausdruck. Enthält personenbezogene Daten – nach Gebrauch vernichten.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{%- set art = frappe.get_doc("PH Terminart", doc.terminart) -%}
{% block titel %}Terminbestätigung {{ doc.referenz }}{% endblock %}
{% block kopfrechts %}Lochau, {{ ph_datum(frappe.utils.nowdate()) }}<br>Referenz {{ doc.referenz }}{% endblock %}
{% block inhalt %}
<div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div>
<div style="min-height:28mm">{{ doc.anrede or "" }}<br>{{ doc.vorname or "" }} {{ doc.nachname }}<br>{% if doc.plz_ort %}{{ doc.plz_ort }}{% endif %}</div>
<h1>Terminbestätigung</h1>
<p>{% if doc.anrede == "Frau" %}Sehr geehrte Frau {{ doc.nachname }},{% elif doc.anrede == "Herr" %}Sehr geehrter Herr {{ doc.nachname }},{% else %}Guten Tag {{ doc.vorname }} {{ doc.nachname }},{% endif %}</p>
<p>wir freuen uns, Ihnen den folgenden Termin zu bestätigen:</p>
<table class="ph-tabelle">
<tr><td style="width:38mm"><b>Was</b></td><td>{{ art.titel_de }}{% if doc.thema %} – {{ doc.thema }}{% endif %}</td></tr>
<tr><td><b>Wann</b></td><td>{{ frappe.utils.format_datetime(doc.start, "EEEE, dd.MM.yyyy") }}, {{ frappe.utils.format_datetime(doc.start, "HH:mm") }}–{{ frappe.utils.format_datetime(doc.ende, "HH:mm") }} Uhr</td></tr>
<tr><td><b>Wo</b></td><td>{% if doc.modus == "Showroom" %}{{ firma.kurzname or firma.firmenname }}, {{ firma.strasse }}, {{ firma.plz }} {{ firma.ort }}{% elif doc.modus == "Video" %}Videoberatung – Zugangslink erhalten Sie 15 Minuten vor Beginn{% elif doc.modus == "Vor Ort" %}bei Ihnen: {{ doc.plz_ort }}{% else %}telefonisch{% if doc.telefon %} unter {{ doc.telefon }}{% endif %}{% endif %}</td></tr>
{% if doc.berater %}<tr><td><b>Ihr Ansprechpartner</b></td><td>{{ frappe.db.get_value("User", doc.berater, "full_name") }}</td></tr>{% endif %}
<tr><td><b>Referenz</b></td><td>{{ doc.referenz }}</td></tr>
</table>
{% if art.hinweis_kunde %}<p class="ph-hinweis">{{ art.hinweis_kunde }}</p>{% endif %}
{% if doc.anliegen %}<h2>Ihr Anliegen</h2><p>{{ doc.anliegen }}</p>{% endif %}
<p>Sollte Ihnen etwas dazwischenkommen, geben Sie uns bitte kurz Bescheid – telefonisch unter {{ firma.telefon or "" }} oder per E-Mail an {{ firma.email }}.</p>
<p>Herzliche Grüße<br><br>{{ frappe.db.get_value("User", doc.berater, "full_name") if doc.berater else "Ihr Platzhirsch-Team" }}<br>{{ firma.kurzname or firma.firmenname }}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{%- set kontakt = frappe.get_doc("PH Kontakt", doc.kontakt) -%}
{% block titel %}Gesprächsprotokoll {{ doc.name }}{% endblock %}
{% block kopfrechts %}Protokoll {{ doc.name }}<br>{{ ph_datum(doc.datum) }}<br>{{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Beratungsgespräch</h1>
<div class="ph-feld"><b>Kunde</b> {{ kontakt.titel }}</div>
<div class="ph-feld"><b>Kontakt</b> {{ kontakt.email or "" }}{% if kontakt.telefon %} · {{ kontakt.telefon }}{% endif %}</div>
<div class="ph-feld"><b>Berater</b> {{ frappe.db.get_value("User", doc.berater, "full_name") or doc.berater }}</div>
<div class="ph-feld"><b>Ort / Dauer</b> {{ doc.ort or "–" }}{% if doc.dauer_min %} · {{ doc.dauer_min }} min{% endif %}</div>
{% if doc.objektart or doc.adresse_objekt %}<div class="ph-feld"><b>Objekt</b> {{ doc.objektart or "" }} {{ doc.adresse_objekt or "" }}</div>{% endif %}
{% if doc.entscheider %}<div class="ph-feld"><b>Beteiligte</b> {{ doc.entscheider }}</div>{% endif %}
<h2>Räume und Wünsche</h2>
<table class="ph-tabelle"><thead><tr><th>Raum</th><th>Wunsch</th><th>Marken</th><th>Priorität</th><th class="zahl">Budget</th></tr></thead><tbody>
{% for r in doc.raeume %}<tr><td>{{ r.raum }}</td><td>{{ r.wunsch }}{% if r.masse %}<br><small>{{ r.masse }}</small>{% endif %}</td><td>{{ r.marken or "" }}</td><td>{{ r.prioritaet }}</td><td class="zahl">{{ ph_betrag(r.budget_cent) if r.budget_cent else "–" }}</td></tr>{% endfor %}
{% if doc.budget_gesamt_cent %}<tr class="ph-summe"><td colspan="4">Budget gesamt</td><td class="zahl">{{ ph_betrag(doc.budget_gesamt_cent) }}</td></tr>{% endif %}
</tbody></table>
<div class="ph-feld"><b>Stil</b> {{ doc.stil or "–" }}</div>
<div class="ph-feld"><b>Zeitrahmen</b> {{ doc.zeitrahmen or "–" }}</div>
{% if doc.zusammenfassung %}<h2>Zusammenfassung</h2><div>{{ doc.zusammenfassung }}</div>{% endif %}
<h2>Nächster Schritt</h2>
<p>{{ doc.naechster_schritt or "–" }}{% if doc.naechster_schritt_bis %} <b>bis {{ ph_datum(doc.naechster_schritt_bis) }}</b>{% endif %}</p>
<p class="ph-hinweis">Internes Protokoll – die Kundenfassung ohne interne Einschätzung.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{%- set a = doc.datenauskunft() -%}
{% block titel %}Datenauskunft {{ doc.name }}{% endblock %}
{% block kopfrechts %}Auskunft nach Art. 15 DSGVO<br>Stand {{ frappe.utils.format_datetime(a.erstellt, "dd.MM.yyyy HH:mm") }}<br>Kontakt {{ doc.name }}{% endblock %}
{% block inhalt %}
<h1>Auskunft über gespeicherte personenbezogene Daten</h1>
<p>Betroffene Person: <b>{{ doc.titel }}</b>. Verantwortlicher: {{ firma.firmenname }}, {{ firma.strasse }}, {{ firma.plz }} {{ firma.ort }}. Zwecke: Beratung, Vertragsanbahnung und -abwicklung, Kundenservice (Art. 6 Abs. 1 lit. b DSGVO); Werbung nur mit Einwilligung (ph_marketing).</p>
<h2>Stammdaten</h2>
<table class="ph-tabelle"><tbody>
{% for k, v in a.stamm.items() %}<tr><td style="width:50mm">{{ _(k) }}</td><td>{{ v }}</td></tr>{% endfor %}
</tbody></table>
{% if a.adressen %}<h2>Weitere Adressen</h2>
<table class="ph-tabelle"><thead><tr><th>Art</th><th>Adresse</th><th>Hinweis</th></tr></thead><tbody>
{% for ad in a.adressen %}<tr><td>{{ ad.art }}</td><td>{{ ad.strasse }}, {{ ad.plz }} {{ ad.ort }}{% if ad.land %}, {{ ad.land }}{% endif %}</td><td>{{ ad.hinweis or "" }}</td></tr>{% endfor %}
</tbody></table>{% endif %}
<h2>Vorgänge</h2>
{% if not a.vorgaenge %}<p>Keine Vorgänge gespeichert.</p>{% endif %}
{% for v in a.vorgaenge %}
<h3>{{ _(v.doctype) }} ({{ v.anzahl }})</h3>
<table class="ph-tabelle"><thead><tr>{% for f in v.felder %}<th>{{ f }}</th>{% endfor %}</tr></thead><tbody>
{% for z in v.zeilen %}<tr>{% for f in v.felder %}<td>{{ z[f] if z[f] is not none else "" }}</td>{% endfor %}</tr>{% endfor %}
</tbody></table>
{% endfor %}
{% if a.kommunikation %}<h2>Kommunikation</h2>
<table class="ph-tabelle"><thead><tr><th>Datum</th><th>Richtung</th><th>Betreff</th></tr></thead><tbody>
{% for k in a.kommunikation %}<tr><td>{{ frappe.utils.format_datetime(k.communication_date, "dd.MM.yyyy HH:mm") }}</td><td>{{ k.sent_or_received }}</td><td>{{ k.subject }}</td></tr>{% endfor %}
</tbody></table>{% endif %}
<h2>Empfänger, Speicherdauer, Rechte</h2>
<p>Empfänger: Auftragsverarbeiter für Hosting, E-Mail-Versand und Zahlungsabwicklung laut Datenschutzerklärung (platzhirsch.studio/datenschutz). Speicherdauer: Anfragen ohne Auftrag bis zu 3 Jahre, Vertragsdaten 7 Jahre (§ 132 BAO). Rechte: Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit, Widerspruch (Art. 16–21 DSGVO), Beschwerde bei der Datenschutzbehörde (dsb.gv.at).</p>
<p class="ph-hinweis">Interne Notizen (Feldebene 1) sind nicht Teil dieser Auskunft, soweit sie keine personenbezogenen Daten der betroffenen Person enthalten – vor Versand durch die Leitung prüfen.</p>
{% endblock %}
